<script setup lang="ts">
import { nextTick, onUnmounted, ref } from 'vue';
import type { components,createIsmClient } from '@ism/api-client';
const props=defineProps<{client:ReturnType<typeof createIsmClient>}>();const emit=defineEmits<{unauthorized:[]}>();
const history=ref<components['schemas']['AdmissionResultPageResponse']['data']>(),busy=ref(false),error=ref(''),panel=ref<HTMLElement>();const abort=new AbortController();let disposed=false;
const names={APPROVED:'准入通过',REJECTED:'准入拒绝',REVISION_REQUIRED:'需要补正'};
async function load(page=0){if(busy.value||disposed)return;busy.value=true;error.value='';try{const result=await props.client.GET('/portal/admission-results',{params:{query:{page,size:10}},signal:abort.signal});if(disposed)return;if(!result.data){if(result.response.status===401)emit('unauthorized');throw new Error(result.response.status===403?'当前租户未开通准入结果查阅。':'读取失败，请稍后刷新重试。');}history.value=result.data.data;}catch(e){if(!disposed){error.value=e instanceof Error?e.message:'读取失败';await nextTick();panel.value?.focus();}}finally{if(!disposed)busy.value=false;}}
onUnmounted(()=>{disposed=true;abort.abort();});
</script>
<template><section class="admission-results" aria-labelledby="admission-results-title" :aria-busy="busy"><div class="heading"><h2 id="admission-results-title">准入审核结果</h2><button class="secondary" :disabled="busy" @click="load()">{{history?'刷新准入结果':'查看已发布准入结果'}}</button></div><p class="help">仅展示邀请方明确发布的审核结果。历史结论不等于当前业务放行，后续准入申请、限制或退出仍以邀请方判定为准。未展示不代表没有审核记录。</p><div v-if="error" ref="panel" role="alert" tabindex="-1" class="error">{{error}}</div><p v-if="busy" role="status">正在读取准入结果…</p><template v-if="history"><p v-if="!history.items.length" class="help">暂无对本企业发布的准入审核结果，请联系邀请方确认。</p><article v-for="row in history.items" :key="row.id"><h3>{{row.applicationNo}} · {{names[row.result]}}</h3><p>采购类别：{{row.purchaseCategory}}</p><p>发布时间（北京时间）：{{new Date(row.publishedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}}</p><p class="comment">对外说明：{{row.publicComment}}</p></article><div class="heading"><button class="secondary" :disabled="busy||history.page===0" @click="load(history.page-1)">上一页准入结果</button><span>第 {{history.page+1}} 页，共 {{history.total}} 条</span><button class="secondary" :disabled="busy||(history.page+1)*history.size>=history.total" @click="load(history.page+1)">下一页准入结果</button></div></template></section></template>
<style scoped>.admission-results{margin-top:28px;padding-top:24px;border-top:1px solid #dce4ed;min-width:0;overflow-wrap:anywhere}.heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}.comment{white-space:pre-wrap;overflow-wrap:anywhere}article{border-bottom:1px solid #dce4ed}button{margin:8px 0}</style>
